-- ============================================
-- La Collecte Dentaire — qualified practices from the Nov–Dec 2025 campaign
-- Generated by scripts/la-collecte-dentaire/build.ts — do not edit by hand.
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f import.sql
--
-- One transaction, safe to re-run. Creates (or reuses) the client « La Collecte
-- Dentaire », a DRAFT mission « La Collecte Dentaire — Relance des cabinets qualifiés », its campaign (pitch and script copied
-- from the client's latest existing campaign when there is one) and 3 lists:
--   LCD 1 · RDV de collecte (nov.–déc. 2025): 157
--   LCD 2 · Boîtes de collecte acceptées (nov.–déc. 2025): 38
--   LCD 3 · À rappeler (nov.–déc. 2025): 258
-- Every touch is in the company's « Historique des appels » field.
-- Exclusion rules are not applied by this file.
-- ============================================

\set ON_ERROR_STOP on
BEGIN;

DO $do$
DECLARE
    v_client   text;
    v_mission  text;
    v_campaign text;
    v_list     text;
    v_count    integer;
    v_icp      text;
    v_pitch    text;
    v_script   text;
BEGIN
    SELECT id INTO v_client FROM "Client"
     WHERE lower(name) LIKE '%collecte dentaire%' OR lower(name) LIKE '%collecte-dentaire%'
     ORDER BY "createdAt" LIMIT 1;
    IF v_client IS NULL THEN
        v_client := 'lcdcli62608e08adc29a8d6dbc9';
        RAISE NOTICE 'Client La Collecte Dentaire created';
    ELSE
        RAISE NOTICE 'Existing client %', v_client;
    END IF;

    SELECT id INTO v_mission FROM "Mission" WHERE "clientId" = v_client AND name = 'La Collecte Dentaire — Relance des cabinets qualifiés' LIMIT 1;
    IF v_mission IS NULL THEN
        v_mission := 'lcdmis6c654debfa4cef1de4995';
        VALUES (v_mission, v_client, 'La Collecte Dentaire — Relance des cabinets qualifiés',
                'Relancer les cabinets dentaires qualifiés de la campagne nov.–déc. 2025 : confirmer les RDV de collecte, faire déposer les boîtes acceptées, requalifier les rappels.',
                'CALL', ARRAY['CALL']::"Channel"[], now(), now() + interval '3 months', 'DRAFT', false, now());
        RAISE NOTICE 'Mission created (DRAFT)';
    END IF;

    SELECT id INTO v_campaign FROM "Campaign" WHERE "missionId" = v_mission ORDER BY "createdAt" LIMIT 1;
    IF v_campaign IS NULL THEN
        SELECT c.icp, c.pitch, c.script INTO v_icp, v_pitch, v_script
          FROM "Campaign" c JOIN "Mission" m ON m.id = c."missionId"
         WHERE m."clientId" = v_client AND m.id <> v_mission
         ORDER BY c."updatedAt" DESC LIMIT 1;
        v_campaign := 'lcdcmp6c8bff2269a89ef7ec3cf';
        VALUES (v_campaign, v_mission, 'Relance cabinets qualifiés',
                COALESCE(v_icp, 'Cabinets dentaires (dentiste ou assistante) ayant accepté un RDV, une boîte de collecte ou un rappel'),
                COALESCE(v_pitch, 'Collecte gratuite des couronnes dentaires du cabinet : un collecteur passe récupérer les couronnes (à partir d''une vingtaine) ou dépose une boîte de collecte où le cabinet les met de côté.'),
                v_script, true, now());
        RAISE NOTICE 'Campaign created (script copied: %)', v_script IS NOT NULL;
    END IF;

    -- LCD 1 · RDV de collecte (nov.–déc. 2025) : 157 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'LCD 1 · RDV de collecte (nov.–déc. 2025)' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'lcdlstfb1858562c90684037391';
        VALUES (v_list, v_mission, 'LCD 1 · RDV de collecte (nov.–déc. 2025)', 'CLIENT', 'Campagne La Collecte Dentaire nov.–déc. 2025 (Drive)', '{"importType":"sql","tier":"1 · RDV de collecte","practices":157}'::jsonb, now());
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'LCD 1 · RDV de collecte (nov.–déc. 2025): already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'LCD 1 · RDV de collecte (nov.–déc. 2025): 157 cabinets imported';
    END IF;

    -- LCD 2 · Boîtes de collecte acceptées (nov.–déc. 2025) : 38 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'LCD 2 · Boîtes de collecte acceptées (nov.–déc. 2025)' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'lcdlst47badae498aed70c32299';
        VALUES (v_list, v_mission, 'LCD 2 · Boîtes de collecte acceptées (nov.–déc. 2025)', 'CLIENT', 'Campagne La Collecte Dentaire nov.–déc. 2025 (Drive)', '{"importType":"sql","tier":"2 · Boîte de collecte acceptée","practices":38}'::jsonb, now());
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'LCD 2 · Boîtes de collecte acceptées (nov.–déc. 2025): already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'LCD 2 · Boîtes de collecte acceptées (nov.–déc. 2025): 38 cabinets imported';
    END IF;

    -- LCD 3 · À rappeler (nov.–déc. 2025) : 258 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'LCD 3 · À rappeler (nov.–déc. 2025)' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'lcdlstaed9caccc8e89c2e310f1';
        VALUES (v_list, v_mission, 'LCD 3 · À rappeler (nov.–déc. 2025)', 'CLIENT', 'Campagne La Collecte Dentaire nov.–déc. 2025 (Drive)', '{"importType":"sql","tier":"3 · À rappeler","practices":258}'::jsonb, now());
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'LCD 3 · À rappeler (nov.–déc. 2025): already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'LCD 3 · À rappeler (nov.–déc. 2025): 258 cabinets imported';
    END IF;

END
$do$;

COMMIT;

-- Check
SELECT l.name AS list, count(DISTINCT co.id) AS cabinets, count(ct.id) AS contacts
FROM "List" l
JOIN "Mission" m ON m.id = l."missionId"
LEFT JOIN "Company" co ON co."listId" = l.id
LEFT JOIN "Contact" ct ON ct."companyId" = co.id
WHERE m.name = 'La Collecte Dentaire — Relance des cabinets qualifiés'
GROUP BY l.name ORDER BY l.name;
