        ('lcdcodc8a59e52be85c584460d', v_list, 'Cabinet Dentaire des Docteurs Vallier et Benicourt', 'France', 'Cabinet dentaire', NULL, NULL, '+33 3 23 56 23 45', '{"Priorité":"1 · RDV de collecte","Dernier résultat":"RDV","Dernier contact":"2025-12-05","Adresse":"1 Rue de la République, 02800 La Fère","Département":"02","Interlocuteur(s)":"Sylvie","Horaires / créneau":"8h - 19h","Collecteur":"VANESSA","Appelé par":"Kevin","Historique des appels":"2025-12-05 10:42 · Kevin · RDV — Sylvie précise qu’ils n’ont pas de couronnes actuellement, mais elle est d’accord pour prendre la boîte. Elle est très sympa.","Sources":"FICHIER DENTISTES FRANCE · 02 ; RDV COMMERCIAUX · VANESSA"}'::jsonb, 'ACTIONABLE', now()),
        ('lcdcoa9bc6b46a1fadae5155c4', v_list, 'Cabinet dentaire dr Becourt', 'France', 'Cabinet dentaire', NULL, NULL, '+33 3 23 23 94 44', '{"Priorité":"1 · RDV de collecte","Dernier résultat":"RDV","Dernier contact":"2025-12-05","Adresse":"8 Rue du Faux Bail, 02250 Marle","Département":"02","Interlocuteur(s)":"Dr Becourt","Horaires / créneau":"ouvert de 9h a 17h a par lheure de déjeuné | 9h-12 / 14h-17h","Collecteur":"VANESSA","Appelé par":"Amélie","Historique des appels":"2025-12-05 10:19 · Amélie · RDV — j''ai eu le dr Becourt il est d''accord pour qu''on lui envoie une boite pour nous garder les prochaine couronnes parce qu''il en a pas pour le moment\n2025-12-05 19:19 · Amélie · RDV — J’ai eu le Dr Becourt. Il est d’accord pour le passage et indique qu’il vous recevra, mais il n’y a pas de couronnes à récupérer cette fois-ci.","Sources":"FICHIER DENTISTES FRANCE · 02 ; RDV COMMERCIAUX · VANESSA"}'::jsonb, 'ACTIONABLE', now()),
